package in.finseq.insurance;
import android.app.Activity;import android.content.Intent;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.graphics.pdf.PdfRenderer;import android.os.Bundle;import android.os.ParcelFileDescriptor;import android.view.*;import android.widget.*;import java.io.*;
public class PdfPreviewActivity extends FinseqActivity{
 static final int SAVE_PDF=781;File cached;PdfRenderer renderer;ParcelFileDescriptor fd;ZoomImageView preview;TextView count;Button save;String attachmentType="";int pageIndex=0,policyId;
 public void onCreate(Bundle b){super.onCreate(b);policyId=getIntent().getIntExtra("policy_id",0);if(policyId<=0){finish();return;}LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"PDF Preview");LinearLayout body=Ui.contentColumn(this);root.addView(body);count=Ui.sub(this,"Loading PDF…");count.setTextIsSelectable(true);body.addView(count);LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.HORIZONTAL);Button prev=Ui.outlineButton(this,"← Previous");Button reset=Ui.outlineButton(this,"Reset Zoom");Button next=Ui.outlineButton(this,"Next →");bar.addView(prev,new LinearLayout.LayoutParams(0,-2,1));bar.addView(reset,new LinearLayout.LayoutParams(0,-2,1));bar.addView(next,new LinearLayout.LayoutParams(0,-2,1));body.addView(bar);body.addView(Ui.sub(this,"Pinch with two fingers to zoom. Drag while zoomed."));save=Ui.greenButton(this,"Download attachment");save.setEnabled(false);body.addView(save);preview=new ZoomImageView(this);preview.setBackgroundColor(android.graphics.Color.WHITE);body.addView(preview,new LinearLayout.LayoutParams(-1,(int)(getResources().getDisplayMetrics().heightPixels*0.65f)));setContentView(Ui.scroll(this,root));prev.setOnClickListener(new View.OnClickListener(){public void onClick(View v){show(pageIndex-1);}});next.setOnClickListener(new View.OnClickListener(){public void onClick(View v){show(pageIndex+1);}});reset.setOnClickListener(new View.OnClickListener(){public void onClick(View v){preview.resetZoom();}});save.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(cached==null||attachmentType.isEmpty())return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(attachmentType.equals("pdf")?"application/pdf":attachmentType.equals("png")?"image/png":"image/jpeg");i.putExtra(Intent.EXTRA_TITLE,"FINSEQ_Policy_"+policyId+"."+attachmentType);startActivityForResult(i,SAVE_PDF);}});Ui.run(this,new Runnable(){public void run(){try{final File file=ApiClient.pdf(PdfPreviewActivity.this,policyId);Ui.ui(PdfPreviewActivity.this,new Runnable(){public void run(){try{cached=file;attachmentType=ApiClient.attachmentType(file);save.setEnabled(true);save.setText(attachmentType.equals("pdf")?"Download PDF":"Download image ("+attachmentType.toUpperCase()+")");if(attachmentType.equals("pdf")){fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);renderer=new PdfRenderer(fd);show(0);}else{BitmapFactory.Options size=new BitmapFactory.Options();size.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),size);int sample=1;while(size.outWidth/sample>1600||size.outHeight/sample>2200)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;Bitmap bitmap=BitmapFactory.decodeFile(file.getAbsolutePath(),options);if(bitmap==null)throw new IOException("Image cannot be decoded");preview.setImageBitmap(bitmap);count.setText("Policy image preview · "+attachmentType.toUpperCase());}}catch(OutOfMemoryError e){count.setText("Attachment is too large to preview. Download the original file.");}catch(Exception e){count.setText("Preview unavailable: "+e.getMessage()+". You can still download the original attachment.");}}});}catch(final Exception e){Ui.ui(PdfPreviewActivity.this,new Runnable(){public void run(){count.setText("Policy #"+policyId+" · Preview failed: "+e.getMessage());}});}}});}

 void show(int index){if(renderer==null||index<0||index>=renderer.getPageCount())return;pageIndex=index;try(PdfRenderer.Page page=renderer.openPage(index)){double scale=Math.min(1800.0/page.getWidth(),Math.sqrt(5000000.0/((double)page.getWidth()*page.getHeight())));int width=Math.max(1,(int)(page.getWidth()*scale));int height=Math.max(1,(int)(page.getHeight()*scale));Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);bitmap.eraseColor(android.graphics.Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);preview.setImageBitmap(bitmap);preview.resetZoom();count.setText("Page "+(index+1)+" of "+renderer.getPageCount());}catch(OutOfMemoryError e){count.setText("Page is too large to preview on this phone");}catch(Exception e){Ui.toast(this,e.getMessage());}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=SAVE_PDF||result!=RESULT_OK||data==null||data.getData()==null||cached==null)return;try(InputStream in=new FileInputStream(cached);OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] buffer=new byte[16384];int size;while((size=in.read(buffer))!=-1)out.write(buffer,0,size);Ui.toast(this,"Policy attachment saved");}catch(Exception e){Ui.toast(this,"Could not save attachment: "+e.getMessage());}}
 protected void onDestroy(){super.onDestroy();try{if(renderer!=null)renderer.close();if(fd!=null)fd.close();}catch(IOException ignored){}if(cached!=null)cached.delete();}
}
